const state = { lang: "fa" };
const FA_DIGITS = ["۱","۲","۳","۴","۵"];
function t(obj) { return obj[state.lang]; }
function stepNum(n) { return state.lang === "fa" ? FA_DIGITS[n - 1] : String(n); }
function el(id) { return document.getElementById(id); }
function esc(s) { return String(s).replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;"); }

/* ================= Page render ================= */

function navParts() {
  return COPY.nav[state.lang].split("·").map(function(s){ return s.trim(); });
}

function renderPage() {
  document.documentElement.lang = state.lang;
  document.documentElement.dir = state.lang === "fa" ? "rtl" : "ltr";
  document.title = "H2 Studio";
  var parts = navParts();
  var anchors = ["services", "work", "process", "about", "contact"];

  el("skipLink").textContent = t(UI.skip);

  var navLinks = el("navLinks");
  navLinks.innerHTML = anchors.map(function(a, i){
    return '<a href="#' + a + '" data-anchor="' + a + '">' + esc(parts[i]) + "</a>";
  }).join("");
  navLinks.setAttribute("aria-label", t(UI.menu));

  var toggle = el("langToggle");
  toggle.textContent = state.lang === "fa" ? "EN" : "فا";
  toggle.setAttribute("aria-label", t(UI.langLabel));

  var ctaLabel = parts[5];
  el("navCta").textContent = ctaLabel;
  el("heroCta").textContent = t(COPY.hero.cta);
  el("workCta").textContent = ctaLabel;
  el("contactCta").textContent = ctaLabel;

  el("heroHeadline").textContent = t(COPY.hero.headline);
  el("heroSub").textContent = t(COPY.hero.sub);

  el("servicesTitle").textContent = parts[0];
  var grid = el("servicesGrid");
  grid.innerHTML = "";
  COPY.services.forEach(function(s, i){
    var card = document.createElement("article");
    card.className = "service-card";
    var html = '<div class="service-num">' + stepNum(i + 1) + "</div>" +
      "<h3>" + esc(t(s.title)) + "</h3><p>" + esc(t(s.desc)) + "</p>";
    if (s.id === "app") {
      html += '<details class="app-flow"><summary>' + esc(t(UI.appFlowTitle)) + "</summary><ol>" +
        APP_FLOW.map(function(st){
          return "<li><b>" + esc(t(st.t)) + "</b>" + esc(t(st.d)) + "</li>";
        }).join("") + "</ol></details>";
    }
    card.innerHTML = html;
    grid.appendChild(card);
  });

  el("workTitle").textContent = t(COPY.portfolio.heading);
  el("workSub").textContent = t(COPY.portfolio.sub);
  var wg = el("workGrid");
  wg.innerHTML = "";
  COPY.portfolio.cards.forEach(function(c, i){
    if (i < SITES.length) {
      var meta = SITES[i];
      var a = document.createElement("a");
      a.className = "card"; a.href = meta.url;
      a.target = "_blank"; a.rel = "noopener";
      a.setAttribute("aria-label", t(c.title) + " — " + meta.name);
      a.innerHTML =
        '<span class="card-thumb"><span class="site-tile" dir="ltr" style="background:linear-gradient(135deg,' +
        meta.color + ',' + meta.color + '99)">' + esc(meta.name) + '</span>' +
        '<span class="tile-hint">' + esc(t(UI.watchSite)) + "</span></span>" +
        '<span class="card-cap"><h3>' + esc(t(c.title)) +
        ' <span dir="ltr">' + esc(meta.name) + "</span>" +
        '<span class="ext-cue">↗ ' + esc(t(UI.externalLink)) + "</span></h3>" +
        '<span class="tag">' + esc(t(c.tag)) + "</span></span>";
      wg.appendChild(a);
    } else {
      var v = VIDEOS[i - SITES.length];
      var b = document.createElement("button");
      b.type = "button"; b.className = "card";
      b.setAttribute("aria-label", t(UI.playVideo) + ": " + t(c.title));
      b.innerHTML =
        '<span class="card-thumb"><img src="' + v.thumb + '" alt="" loading="lazy">' +
        '<span class="play-badge" aria-hidden="true">▶</span></span>' +
        '<span class="card-cap"><h3>' + esc(t(c.title)) + "</h3>" +
        '<span class="tag">' + esc(t(c.tag)) + "</span></span>";
      b.addEventListener("click", function(){ openVideo(c.title, v.src); });
      wg.appendChild(b);
    }
  });

  el("processTitle").textContent = t(COPY.process.heading);
  var ps = el("processSteps");
  ps.innerHTML = "";
  COPY.process.steps.forEach(function(s, i){
    var li = document.createElement("li");
    li.innerHTML = '<div class="step-num" aria-hidden="true">' + stepNum(i + 1) + "</div>" +
      "<h3>" + esc(t(s.title)) + "</h3><p>" + esc(t(s.desc)) + "</p>";
    ps.appendChild(li);
  });

  el("aboutTitle").textContent = t(COPY.about.heading);
  el("aboutBody").textContent = t(COPY.about.body);

  el("contactTitle").textContent = parts[4];
  el("contactBody").textContent = t(UI.contactBody);

  el("footerTagline").textContent = t(COPY.footer.tagline);
  el("wizardClose").textContent = "×";
  el("wizardClose").setAttribute("aria-label", t(UI.close));
  el("videoClose").textContent = "×";
  el("videoClose").setAttribute("aria-label", t(UI.close));
}

/* ================= Wizard ================= */

var wiz = { open: false, step: 1, done: false, type: null, brief: {}, budget: null, timeline: null, name: "", contact: "" };
var wizOpener = null;

function wizStepDef(i) { return WIZARD.steps[i - 1]; }

function openWizard(opener) {
  wizOpener = opener || document.activeElement;
  wiz.open = true; wiz.step = 1; wiz.done = false;
  wiz.type = null; wiz.brief = {}; wiz.budget = null; wiz.timeline = null; wiz.name = ""; wiz.contact = "";
  el("wizard").hidden = false;
  document.body.style.overflow = "hidden";
  renderWizardStep();
  el("wizardClose").focus();
}

function closeWizard(force) {
  if (!wiz.open) return;
  if (!force && !wiz.done && wiz.step > 1) {
    if (!window.confirm(t(UI.guardClose))) return;
  }
  wiz.open = false;
  el("wizard").hidden = true;
  document.body.style.overflow = "";
  if (wizOpener && wizOpener.focus) wizOpener.focus();
}

function fieldError(fieldEl, msg) {
  fieldEl.classList.add("invalid");
  var m = fieldEl.querySelector(".error-msg");
  if (m) m.textContent = msg;
}
function clearErrors(root) {
  root.querySelectorAll(".invalid").forEach(function(f){ f.classList.remove("invalid"); });
  root.querySelectorAll(".error-msg").forEach(function(m){ m.textContent = ""; });
}

function isOptionalText(q) {
  return q.kind === "text" && /اختیاری|optional/i.test(q.q.fa + " " + q.q.en);
}
function briefKey(i) { return "q" + i; }

function validateStep() {
  var body = el("wizardBody");
  clearErrors(body);
  var ok = true;
  if (wiz.step === 1) {
    if (!wiz.type) {
      var wrap = body.querySelector(".wiz-cards");
      wrap.classList.add("invalid");
      var m = body.querySelector("#stepErr"); m.textContent = t(UI.errPick);
      ok = false;
    }
  } else if (wiz.step === 2) {
    wizStepDef(2).per_type[wiz.type].forEach(function(q, i){
      var key = briefKey(i);
      var val = wiz.brief[key];
      var fel = body.querySelector('[data-field="' + key + '"]');
      if (q.kind === "choice") {
        if (val == null) { fieldError(fel, t(UI.errPick)); ok = false; }
      } else if (!isOptionalText(q)) {
        if (!val || String(val).trim().length < WIZARD.validation.min_text_length) {
          fieldError(fel, t(UI.errRequired)); ok = false;
        }
      }
    });
  } else if (wiz.step === 3) {
    if (wiz.budget == null || wiz.timeline == null) {
      var m3 = body.querySelector("#stepErr"); m3.textContent = t(UI.errStep3); ok = false;
    }
  } else if (wiz.step === 4) {
    var nameF = body.querySelector('[data-field="name"]');
    var conF = body.querySelector('[data-field="contact_handle"]');
    if (!wiz.name.trim() || wiz.name.trim().length < WIZARD.validation.min_text_length) {
      fieldError(nameF, t(UI.errName)); ok = false;
    }
    if (!validContact(wiz.contact)) { fieldError(conF, t(UI.errContact)); ok = false; }
  }
  if (!ok) {
    var first = body.querySelector(".invalid input, .invalid textarea") || body.querySelector("#stepErr");
    if (first && first.focus) first.focus();
  }
  return ok;
}

function validContact(v) {
  v = String(v || "").trim();
  var digits = (v.match(/\d/g) || []).length;
  if (digits >= 7) return true;
  if (/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v)) return true;
  if (/^@[\w.]{2,}$/.test(v)) return true;
  return false;
}

function chip(label, pressed, attrs) {
  return '<button type="button" class="chip" aria-pressed="' + pressed + '"' + (attrs || "") + ">" + esc(label) + "</button>";
}

function renderWizardStep() {
  var body = el("wizardBody");
  var foot = el("wizardFoot");
  var stepOf = el("wizardStepOf");
  var prog = el("wizard").querySelector(".progress");
  var fill = el("progressFill");

  if (wiz.done) { renderSuccess(); return; }

  stepOf.style.display = "";
  prog.style.display = "";
  foot.style.display = "";
  stepOf.textContent = t(WIZARD.ui.step_of).replace("{n}", stepNum(wiz.step));
  fill.style.width = (wiz.step / 4 * 100) + "%";
  el("wizardBack").textContent = t(WIZARD.ui.back);
  el("wizardBack").style.visibility = wiz.step === 1 ? "hidden" : "visible";
  el("wizardNext").textContent = wiz.step === 4 ? t(WIZARD.ui.send_whatsapp) : t(WIZARD.ui.next);

  var html = "";
  if (wiz.step === 1) {
    var def = wizStepDef(1);
    html = "<h2 id=\"wizardTitle\">" + esc(t(def.title)) + "</h2>" +
      '<div class="wiz-cards" role="group">' +
      def.options.map(function(o){
        return '<button type="button" class="wiz-card" data-type="' + o.id + '" aria-pressed="' + (wiz.type === o.id) + '">' + esc(t(o.label)) + "</button>";
      }).join("") + "</div>" +
      '<div class="error-msg" id="stepErr" role="alert"></div>';
  } else if (wiz.step === 2) {
    var def2 = wizStepDef(2);
    var qs = def2.per_type[wiz.type];
    html = "<h2 id=\"wizardTitle\">" + esc(t(def2.title)) + "</h2>";
    qs.forEach(function(q, i){
      var key = briefKey(i);
      html += '<div class="field" data-field="' + key + '">';
      if (q.kind === "choice") {
        html += '<span class="q-label" id="ql' + i + '">' + esc(t(q.q)) + "</span>" +
          '<div class="chips" role="group" aria-labelledby="ql' + i + '">' +
          q.options.map(function(o, oi){
            return chip(t(o), wiz.brief[key] === oi, ' data-q="' + i + '" data-oi="' + oi + '"');
          }).join("") + "</div>";
      } else {
        var opt = isOptionalText(q) ? ' <span class="opt-tag">(' + (state.lang === "fa" ? "اختیاری" : "optional") + ")</span>" : "";
        html += '<label for="qi' + i + '">' + esc(t(q.q)) + opt + "</label>" +
          '<textarea id="qi' + i + '" data-textq="' + i + '" enterkeyhint="next" rows="2">' +
          esc(wiz.brief[key] || "") + "</textarea>";
      }
      html += '<div class="error-msg" role="alert"></div></div>';
    });
  } else if (wiz.step === 3) {
    var def3 = wizStepDef(3);
    html = "<h2 id=\"wizardTitle\">" + esc(t(def3.title)) + "</h2>" +
      '<div class="group-label">' + esc(t(def3.title).split("(")[0].trim()) + "</div>" +
      '<div class="chips" role="group">' +
      def3.budget_ranges.map(function(r, i){
        return chip(t(r), wiz.budget === i, ' data-budget="' + i + '"');
      }).join("") + "</div>" +
      '<div class="group-label">' + esc(t(UI.timelineLabel)) + "</div>" +
      '<div class="chips" role="group">' +
      def3.timelines.map(function(r, i){
        return chip(t(r), wiz.timeline === i, ' data-timeline="' + i + '"');
      }).join("") + "</div>" +
      '<div class="error-msg" id="stepErr" role="alert"></div>';
  } else if (wiz.step === 4) {
    var def4 = wizStepDef(4);
    html = "<h2 id=\"wizardTitle\">" + esc(t(def4.title)) + "</h2>";
    def4.fields.forEach(function(f){
      var fid = f.id === "name" ? "name" : "contact_handle";
      var val = fid === "name" ? wiz.name : wiz.contact;
      var attrs = fid === "name"
        ? 'inputmode="text" enterkeyhint="next" autocomplete="name"'
        : 'inputmode="text" enterkeyhint="send" autocomplete="tel"';
      html += '<div class="field" data-field="' + fid + '">' +
        '<label for="wf-' + fid + '">' + esc(t(f.label)) + "</label>" +
        '<input type="text" id="wf-' + fid + '" data-wf="' + fid + '" value="' + esc(val) + '" ' + attrs + ">" +
        (f.hint ? '<div class="field-hint">' + esc(t(f.hint)) + "</div>" : "") +
        '<div class="error-msg" role="alert"></div></div>';
    });
  }

  body.innerHTML = html;

  body.querySelectorAll("[data-type]").forEach(function(b){
    b.addEventListener("click", function(){
      wiz.type = b.getAttribute("data-type");
      body.querySelectorAll("[data-type]").forEach(function(x){ x.setAttribute("aria-pressed", x === b ? "true" : "false"); });
      body.querySelector("#stepErr").textContent = "";
    });
  });
  body.querySelectorAll("[data-q]").forEach(function(b){
    b.addEventListener("click", function(){
      var qi = +b.getAttribute("data-q"), oi = +b.getAttribute("data-oi");
      wiz.brief[briefKey(qi)] = oi;
      body.querySelectorAll('[data-q="' + qi + '"]').forEach(function(x){ x.setAttribute("aria-pressed", x === b ? "true" : "false"); });
      var fel = body.querySelector('[data-field="' + briefKey(qi) + '"]');
      fel.classList.remove("invalid"); fel.querySelector(".error-msg").textContent = "";
    });
  });
  body.querySelectorAll("[data-textq]").forEach(function(ta){
    ta.addEventListener("input", function(){ wiz.brief[briefKey(+ta.getAttribute("data-textq"))] = ta.value; });
  });
  body.querySelectorAll("[data-budget]").forEach(function(b){
    b.addEventListener("click", function(){
      wiz.budget = +b.getAttribute("data-budget");
      body.querySelectorAll("[data-budget]").forEach(function(x){ x.setAttribute("aria-pressed", x === b ? "true" : "false"); });
      body.querySelector("#stepErr").textContent = "";
    });
  });
  body.querySelectorAll("[data-timeline]").forEach(function(b){
    b.addEventListener("click", function(){
      wiz.timeline = +b.getAttribute("data-timeline");
      body.querySelectorAll("[data-timeline]").forEach(function(x){ x.setAttribute("aria-pressed", x === b ? "true" : "false"); });
      body.querySelector("#stepErr").textContent = "";
    });
  });
  body.querySelectorAll("[data-wf]").forEach(function(inp){
    inp.addEventListener("input", function(){
      if (inp.getAttribute("data-wf") === "name") wiz.name = inp.value; else wiz.contact = inp.value;
    });
    inp.addEventListener("keydown", function(e){
      if (e.key === "Enter") { e.preventDefault(); el("wizardNext").click(); }
    });
  });

  body.scrollTop = 0;
  var focusable = body.querySelector("button, input, textarea");
  if (focusable) focusable.focus();
}

function buildMessage() {
  var typeOpt = wizStepDef(1).options.filter(function(o){ return o.id === wiz.type; })[0];
  var tpl = t(WIZARD.wa_template);
  var qs = wizStepDef(2).per_type[wiz.type];
  var briefLines = qs.map(function(q, i){
    var val = wiz.brief[briefKey(i)];
    if (val == null || String(val).trim() === "") return null;
    var ans = q.kind === "choice" ? t(q.options[val]) : String(val).trim();
    return t(q.q) + ": " + ans;
  }).filter(Boolean).join("\n");
  return tpl
    .replace("{project_type}", t(typeOpt.label))
    .replace("{brief_lines}", briefLines)
    .replace("{budget_range}", t(wizStepDef(3).budget_ranges[wiz.budget]))
    .replace("{timeline}", t(wizStepDef(3).timelines[wiz.timeline]))
    .replace("{name}", wiz.name.trim())
    .replace("{contact_handle}", wiz.contact.trim());
}

function waLink() {
  return "https://wa.me/" + WHATSAPP_NUMBER + "?text=" + encodeURIComponent(buildMessage());
}

function renderSuccess() {
  el("wizardStepOf").style.display = "none";
  el("wizard").querySelector(".progress").style.display = "none";
  el("wizardFoot").style.display = "none";
  var body = el("wizardBody");
  var link = waLink();
  body.innerHTML =
    '<div class="success">' +
    '<svg class="success-icon" viewBox="0 0 84 84" aria-hidden="true"><circle cx="42" cy="42" r="37" fill="none" stroke="#4fd08a" stroke-width="5"/><path d="M28 43l10 10 18-21" fill="none" stroke="#4fd08a" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"/></svg>' +
    "<h2 id=\"wizardTitle\">" + esc(t(WIZARD.ui.success_title)) + "</h2>" +
    "<p>" + esc(t(WIZARD.ui.success_body)) + "</p>" +
    '<a class="btn btn-wa" href="' + link + '" target="_blank" rel="noopener">' + esc(t(UI.waButton)) + "</a>" +
    '<div class="copy-row"><button type="button" class="copy-btn" id="copyMsgBtn">' + esc(t(UI.copyMessage)) + '</button><span class="copy-ok" id="copyOk" hidden>' + esc(t(UI.copied)) + "</span></div>" +
    '<button type="button" class="restart-link" id="restartBtn">' + esc(t(UI.restart)) + "</button>" +
    "</div>";
  el("copyMsgBtn").addEventListener("click", function(){ copyMessageText(buildMessage()); });
  el("restartBtn").addEventListener("click", function(){
    wiz.step = 1; wiz.done = false;
    wiz.type = null; wiz.brief = {}; wiz.budget = null; wiz.timeline = null; wiz.name = ""; wiz.contact = "";
    renderWizardStep();
  });
  body.scrollTop = 0;
  body.querySelector(".btn-wa").focus();
}

function copyMessageText(text) {
  var okEl = el("copyOk");
  function done(){ okEl.hidden = false; setTimeout(function(){ okEl.hidden = true; }, 2500); }
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(text).then(done, function(){ fallbackCopy(text); done(); });
  } else { fallbackCopy(text); done(); }
}
function fallbackCopy(text) {
  var ta = document.createElement("textarea");
  ta.value = text; ta.setAttribute("readonly", "");
  ta.style.position = "fixed"; ta.style.opacity = "0";
  document.body.appendChild(ta); ta.select();
  try { document.execCommand("copy"); } catch (e) {}
  ta.remove();
}

/* ================= Video modal ================= */

var videoOpener = null;
function openVideo(titleObj, src) {
  videoOpener = document.activeElement;
  el("videoModalTitle").textContent = t(titleObj);
  var v = el("modalVideo");
  v.src = src;
  el("videoModal").hidden = false;
  document.body.style.overflow = "hidden";
  el("videoClose").focus();
  var p = v.play();
  if (p && p.catch) p.catch(function(){});
}
function closeVideo() {
  var v = el("modalVideo");
  v.pause(); v.removeAttribute("src"); v.load();
  el("videoModal").hidden = true;
  if (!wiz.open) document.body.style.overflow = "";
  if (videoOpener && videoOpener.focus) videoOpener.focus();
}

/* ================= Focus trap + ESC ================= */

function trapTab(e, container) {
  if (e.key !== "Tab") return;
  var f = Array.prototype.filter.call(
    container.querySelectorAll("button, [href], input, textarea, [tabindex]:not([tabindex='-1'])"),
    function(x){ return !x.disabled && x.offsetParent !== null; }
  );
  if (!f.length) return;
  var first = f[0], last = f[f.length - 1];
  if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
  else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
}

document.addEventListener("keydown", function(e){
  if (!el("wizard").hidden) trapTab(e, el("wizard"));
  else if (!el("videoModal").hidden) trapTab(e, el("videoModal"));
  if (e.key === "Escape") {
    if (!el("videoModal").hidden) closeVideo();
    else if (!el("wizard").hidden) closeWizard(false);
  }
});

/* ================= Wiring ================= */

function init() {
  renderPage();

  document.querySelectorAll("[data-wizard-open]").forEach(function(b){
    b.addEventListener("click", function(){ openWizard(b); });
  });

  el("wizardClose").addEventListener("click", function(){ closeWizard(false); });
  el("wizardBack").addEventListener("click", function(){
    if (wiz.step > 1) { wiz.step--; renderWizardStep(); }
  });
  el("wizardNext").addEventListener("click", function(){
    if (!validateStep()) return;
    if (wiz.step < 4) { wiz.step++; renderWizardStep(); }
    else { wiz.done = true; renderWizardStep(); }
  });

  el("videoClose").addEventListener("click", closeVideo);
  el("videoModal").addEventListener("click", function(e){
    if (e.target === el("videoModal")) closeVideo();
  });
  el("wizard").addEventListener("click", function(e){
    if (e.target === el("wizard")) closeWizard(false);
  });

  el("langToggle").addEventListener("click", function(){
    state.lang = state.lang === "fa" ? "en" : "fa";
    renderPage();
    if (wiz.open) renderWizardStep();
    if (!el("videoModal").hidden) {
      var idx = el("modalVideo").src.indexOf("qatre") !== -1 ? 0 : 1;
      el("videoModalTitle").textContent = t(COPY.portfolio.cards[SITES.length + idx].title);
    }
  });

  var ham = el("hamburger"), links = el("navLinks");
  ham.setAttribute("aria-label", t(UI.menu));
  ham.addEventListener("click", function(){
    var open = links.classList.toggle("open");
    ham.setAttribute("aria-expanded", open ? "true" : "false");
  });
  links.addEventListener("click", function(){ links.classList.remove("open"); ham.setAttribute("aria-expanded", "false"); });

  var nav = el("nav");
  window.addEventListener("scroll", function(){
    nav.classList.toggle("scrolled", window.scrollY > 40);
  }, { passive: true });

  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(en){
      if (en.isIntersecting) {
        links.querySelectorAll("a").forEach(function(a){
          a.classList.toggle("active", a.getAttribute("data-anchor") === en.target.id);
        });
      }
    });
  }, { rootMargin: "-40% 0px -55% 0px" });
  ["services", "work", "process", "about", "contact"].forEach(function(id){ io.observe(el(id)); });

  var hv = el("heroVideo");
  hv.addEventListener("canplay", function(){ hv.classList.add("ready"); });
  hv.addEventListener("error", function(){ hv.style.display = "none"; });
  var srcEl = hv.querySelector("source");
  if (srcEl) srcEl.addEventListener("error", function(){ hv.style.display = "none"; });
}

if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", init);
else init();
